         ->assertUnauthorized();
}

public function test_login_returns_token(): void
{
    $user = User::factory()->create([
        'password' => bcrypt('password123'),
    ]);

    $this->postJson('/api/auth/login', [
        'email' => $user->email,
        'password' => 'password123',
    ])
    ->assertOk()
    ->assertJsonStructure(['token', 'user']);
}
