namespace Database\Seeders;

use App\Actions\CompanyEmployeeAttachAction;
use App\Actions\EmployeeProjectAssignAction;
use App\Models\Company;
use App\Models\Employee;
use App\Models\Project;
use App\Models\Task;
use App\Models\TimeEntry;
use Illuminate\Database\Console\Seeds\WithoutModelEvents;
use Illuminate\Database\Seeder;

class DatabaseSeeder extends Seeder
{
    use WithoutModelEvents;

    /**
     * Seed the application's database.
     */
    public function run(
        CompanyEmployeeAttachAction $attachEmployee,
        EmployeeProjectAssignAction $assignProject,
    ): void {
        $acme = Company::query()->create(['name' => 'Acme Operations']);
        $globex = Company::query()->create(['name' => 'Globex Services']);

        $ava = Employee::query()->create(['name' => 'Ava Chen', 'email' => 'ava.chen@example.test']);
        $ben = Employee::query()->create(['name' => 'Ben Carter', 'email' => 'ben.carter@example.test']);
        $cora = Employee::query()->create(['name' => 'Cora Diaz', 'email' => 'cora.diaz@example.test']);
        $dev = Employee::query()->create(['name' => 'Dev Malik', 'email' => 'dev.malik@example.test']);

        foreach ([$ava, $ben, $cora] as $employee) {
            $attachEmployee->execute($acme, $employee);
        }

        foreach ([$cora, $dev] as $employee) {
            $attachEmployee->execute($globex, $employee);
        }

        $acmeWebsite = Project::query()->create(['company_id' => $acme->id, 'name' => 'Website Redesign']);
        $acmeMobile = Project::query()->create(['company_id' => $acme->id, 'name' => 'Mobile Launch']);
        $globexMigration = Project::query()->create(['company_id' => $globex->id, 'name' => 'Data Migration']);
        $globexSupport = Project::query()->create(['company_id' => $globex->id, 'name' => 'Client Support']);

        Task::query()->create(['company_id' => $acme->id, 'name' => 'Planning']);
        $acmeDevelopment = Task::query()->create(['company_id' => $acme->id, 'name' => 'Development']);
        $acmeReview = Task::query()->create(['company_id' => $acme->id, 'name' => 'Review']);

        Task::query()->create(['company_id' => $globex->id, 'name' => 'Discovery']);
        $globexCleanup = Task::query()->create(['company_id' => $globex->id, 'name' => 'Cleanup']);
        $globexSupportTask = Task::query()->create(['company_id' => $globex->id, 'name' => 'Support']);

        $assignProject->execute($ava, $acmeWebsite, $acme);
        $assignProject->execute($ava, $acmeMobile, $acme);
        $assignProject->execute($ben, $acmeWebsite, $acme);
        $assignProject->execute($cora, $acmeMobile, $acme);
        $assignProject->execute($cora, $globexMigration, $globex);
        $assignProject->execute($dev, $globexMigration, $globex);
        $assignProject->execute($dev, $globexSupport, $globex);

        TimeEntry::query()->create([
            'company_id' => $acme->id,
            'employee_id' => $ava->id,
            'project_id' => $acmeWebsite->id,
            'task_id' => $acmeDevelopment->id,
            'entry_date' => '2026-01-05',
            'hours' => 4.00,
        ]);

        TimeEntry::query()->create([
            'company_id' => $acme->id,
            'employee_id' => $ava->id,
            'project_id' => $acmeWebsite->id,
            'task_id' => $acmeReview->id,
            'entry_date' => '2026-01-05',
            'hours' => 2.00,
        ]);

        TimeEntry::query()->create([
            'company_id' => $globex->id,
            'employee_id' => $dev->id,
            'project_id' => $globexSupport->id,
            'task_id' => $globexSupportTask->id,
            'entry_date' => '2026-01-06',
            'hours' => 3.50,
        ]);

        TimeEntry::query()->create([
            'company_id' => $globex->id,
            'employee_id' => $cora->id,
            'project_id' => $globexMigration->id,
            'task_id' => $globexCleanup->id,
            'entry_date' => '2026-01-07',
            'hours' => 5.25,
        ]);
    }
}

