   773	class TimeEntryFactory extends Factory
   774	{
   775	    /**
   776	     * Define the model's default state.
   777	     *
   778	     * @return array<string, mixed>
   779	     */
   780	    public function definition(): array
   781	    {
   782	        return [
   783	            'employee_id' => Employee::factory(),
   784	            'entry_date' => fake()->dateTimeBetween('-1 month', 'now')->format('Y-m-d'),
   785	            'hours' => fake()->randomFloat(2, 0.25, 8),
   786	        ];
   787	    }
   788	
   789	    /**
   790	     * Configure generated project and task records to match the time entry company.
   791	     */
   792	    public function configure(): static
   793	    {
   794	        return $this->afterMaking(function (TimeEntry $timeEntry): void {
   795	            $company = $this->resolveCompany($timeEntry);
   796	
   797	            $timeEntry->company_id = $company->id;
   798	
   799	            if ($timeEntry->project_id === null) {
   800	                $timeEntry->project()->associate(Project::factory()->for($company)->create());
   801	            }
   802	
   803	            if ($timeEntry->task_id === null) {
   804	                $timeEntry->task()->associate(Task::factory()->for($company)->create());
   805	            }
   806	        });
   807	    }
   808	
   809	    private function resolveCompany(TimeEntry $timeEntry): Company
   810	    {
   811	        if ($timeEntry->project_id !== null) {
   812	            return Project::query()->findOrFail($timeEntry->project_id)->company;
   813	        }
   814	
   815	        if ($timeEntry->task_id !== null) {
   816	            return Task::query()->findOrFail($timeEntry->task_id)->company;
   817	        }
   818	
   819	        if ($timeEntry->company_id !== null) {
   820	            return Company::query()->findOrFail($timeEntry->company_id);
   821	        }
   822	
   823	        return Company::factory()->create();
   824	    }
   825	}
