25	            'employee_id' => Employee::factory(),
26	            'entry_date' => fake()->dateTimeBetween('-1 month', 'now')->format('Y-m-d'),
27	            'hours' => fake()->randomFloat(2, 0.25, 8),
28	        ];
29	    }
30	
31	    /**
32	     * Configure generated project and task records to match the time entry company.
33	     */
34	    public function configure(): static
35	    {
36	        return $this->afterMaking(function (TimeEntry $timeEntry): void {
37	            $company = $this->resolveCompany($timeEntry);
38	
39	            $timeEntry->company_id = $company->id;
40	
41	            if ($timeEntry->project_id === null) {
42	                $timeEntry->project()->associate(Project::factory()->for($company)->create());
43	            }
44	
45	            if ($timeEntry->task_id === null) {
46	                $timeEntry->task()->associate(Task::factory()->for($company)->create());
47	            }
48	        });
49	    }
50	
51	    private function resolveCompany(TimeEntry $timeEntry): Company
52	    {
53	        if ($timeEntry->project_id !== null) {
54	            return Project::query()->findOrFail($timeEntry->project_id)->company;
55	        }
56	
57	        if ($timeEntry->task_id !== null) {
58	            return Task::query()->findOrFail($timeEntry->task_id)->company;
59	        }
60	
61	        if ($timeEntry->company_id !== null) {
62	            return Company::query()->findOrFail($timeEntry->company_id);
63	        }
64	
65	        return Company::factory()->create();
66	    }
