            ] : null,
        ];
    }

    private function priorityCaseExpression(): string
    {
        return sprintf(
            "case priority when '%s' then 4 when '%s' then 3 when '%s' then 2 when '%s' then 1 else 0 end",
            Priority::Urgent,
            Priority::High,
