        $this->getJson("/api/v1/time-entries?filter[company_id]={$company->id}")
            ->assertOk()
            ->assertJsonPath('data.0.id', $includedEntry->id)
            ->assertJsonMissing(['id' => $outsideEntry->id]);
    }

