                continue;
            }

            if (
                data_get($otherEntry, 'employee_id') === $employeeId
                && self::dateKey(data_get($otherEntry, 'entry_date')) === $entryDate
                && data_get($otherEntry, 'project_id') !== $projectId
            ) {
                $validator->errors()->add("entries.{$index}.project_id", 'An employee can only work on one project per date.');

                return;
            }
        }
    }

    /**
     * @param  array<string, mixed>  $entry
     */
    private static function validateExistingProjectConflict(Validator $validator, array $entry, int|string $index): void
    {
        $employeeId = data_get($entry, 'employee_id');
        $projectId = data_get($entry, 'project_id');
        $entryDate = self::dateKey(data_get($entry, 'entry_date'));

        if (! is_string($employeeId) || ! is_string($projectId) || $entryDate === null) {
            return;
        }

        if (TimeEntry::query()
            ->where('employee_id', $employeeId)
            ->whereDate('entry_date', $entryDate)
            ->where('project_id', '!=', $projectId)
            ->exists()) {
            $validator->errors()->add("entries.{$index}.project_id", 'An employee already has a different project on this date.');
        }
    }

    private static function dateKey(mixed $value): ?string
    {
        if (! is_string($value)) {
            return null;
        }

        try {
            return Carbon::parse($value)->toDateString();
        } catch (Throwable) {
            return null;
        }
    }
}

