use App\Models\Task;
use App\Models\TimeEntry;
use Illuminate\Database\Eloquent\Collection as EloquentCollection;
use Illuminate\Support\Facades\DB;

readonly class CreateTimeEntryBatchAction
{
    public function __construct(
        private TimeEntryBatchBusinessValidator $validator,
        private TimeEntryCreateAction $createAction,
    ) {}

    /**
     * @return EloquentCollection<int, TimeEntry>
     */
    public function execute(TimeEntryBatchData $data): EloquentCollection
    {
        $this->validator->validate($data);

        $companies = Company::query()->whereKey(collect($data->entries)->pluck('company_id'))->get()->keyBy('id');
        $employees = Employee::query()->whereKey(collect($data->entries)->pluck('employee_id'))->get()->keyBy('id');
        $projects = Project::query()->whereKey(collect($data->entries)->pluck('project_id'))->get()->keyBy('id');
        $tasks = Task::query()->whereKey(collect($data->entries)->pluck('task_id'))->get()->keyBy('id');

        return DB::transaction(function () use ($data, $companies, $employees, $projects, $tasks): EloquentCollection {
            $createdEntries = new EloquentCollection;

            foreach ($data->entries as $entry) {
                $createdEntries->push($this->createAction->execute(new TimeEntryData(
                    company: $companies->get($entry['company_id']),
                    employee: $employees->get($entry['employee_id']),
                    project: $projects->get($entry['project_id']),
                    task: $tasks->get($entry['task_id']),
                    entry_date: $entry['entry_date'],
                    hours: $entry['hours'],
                )));
            }

            return $createdEntries->load([
