function addRow() {
    rows.value.push({
        company: props.selectedCompanyId ?? null,
        date: '',
        employee: null,
        project: null,
        task: null,
        hours: '',
    });
}

function duplicateActiveRow() {
    const source = rows.value[activeCell.row] ?? rows.value[0];
    rows.value.splice(activeCell.row + 1, 0, { ...source });
    setActiveCell(activeCell.row + 1, 0);
}

function clearRows() {
    rows.value = [
        {
