            date: '',
            employee: null,
            project: null,
            task: null,
            hours: '',
        },
    ];
    setActiveCell(0, 0);
}

function cellPlaceholder(column) {
    return {
        company: 'Select company',
        date: 'Set date',
        employee: 'Select employee',
        project: 'Select project',
        task: 'Select task',
        hours: '0.00',
    }[column];
}
</script>

