                'hours' => $entry['hours'],
                'created_at' => $timestamp,
                'updated_at' => $timestamp,
            ];
        });

        return DB::transaction(function () use ($ids, $rows): EloquentCollection {
            TimeEntry::query()->insert($rows->all());

