        <div v-if="submitError" class="border-b border-border px-3 py-2 text-sm text-destructive">
            {{ submitError }}
        </div>
        <div v-else-if="submitState === 'submitted'" class="border-b border-border px-3 py-2 text-sm text-[#79d98d]">
