        </div>

        <Table class="[&_table]:table-fixed">
            <TableHeader>
                <TableRow class="bg-background/70 hover:bg-background/70">
                    <TableHead class="w-12 text-center">#</TableHead>
                    <TableHead
                        v-for="column in spreadsheetColumns"
                        :key="column"
                        :class="column === 'hours' ? 'w-28 text-right' : 'w-44'"
