import { computed, nextTick, ref } from 'vue';
import { Check, ChevronsUpDown } from 'lucide-vue-next';
import { Button } from '@/components/ui/button';
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from '@/components/ui/command';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { cn } from '@/lib/utils';

const props = defineProps({
    active: { type: Boolean, default: false },
    disabled: { type: Boolean, default: false },
    error: { type: [String, null], default: null },
    isLoading: { type: Boolean, default: false },
    modelValue: { type: [String, null], default: null },
    options: { type: Array, default: () => [] },
    placeholder: { type: String, required: true },
    searchPlaceholder: { type: String, default: 'Filter options...' },
});

const emit = defineEmits(['commit', 'focus', 'keydown', 'navigate', 'select']);

const open = ref(false);
const trigger = ref(null);

const selectedOption = computed(() => props.options.find((option) => option.id === props.modelValue) ?? null);
const selectedLabel = computed(() => selectedOption.value?.name ?? props.placeholder);

function focus() {
    if (typeof trigger.value?.focus === 'function') {
        trigger.value.focus();
        return;
    }

    trigger.value?.$el?.focus();
}

async function openPicker() {
    if (props.disabled) {
        return;
    }

    open.value = true;
    await nextTick();
}

async function selectOption(option) {
    emit('select', option);
    open.value = false;

    await nextTick();
    emit('commit');
}

function handleTriggerKeydown(event) {
    if (!['Enter', ' ', 'F2'].includes(event.key)) {
        emit('keydown', event);
        return;
    }

    event.preventDefault();
    openPicker();
}

function handleEditorKeydown(event) {
    if (event.key === 'Escape') {
        event.preventDefault();
        open.value = false;
        focus();
        return;
    }

    if (event.key !== 'Tab') {
        return;
    }

    event.preventDefault();
    open.value = false;
    emit('navigate', event.shiftKey ? -1 : 1);
}

defineExpose({ focus });
</script>

