import { apiGet, apiPost } from './client';

export async function getCompanies() {
    const payload = await apiGet('/api/v1/companies');

    return payload.data ?? [];
}

export async function getCompanyEmployees(companyId) {
    const payload = await apiGet(`/api/v1/companies/${companyId}/employees`);

    return payload.data ?? [];
}

export async function getCompanyProjects(companyId, employeeId = null) {
    const params = new URLSearchParams();

    if (employeeId) {
        params.set('filter[employee_id]', employeeId);
    }

    const query = params.toString();
    const payload = await apiGet(`/api/v1/companies/${companyId}/projects${query ? `?${query}` : ''}`);

    return payload.data ?? [];
}

export async function getCompanyTasks(companyId) {
    const payload = await apiGet(`/api/v1/companies/${companyId}/tasks`);

    return payload.data ?? [];
}

export async function createTimeEntries(entries) {
    const payload = await apiPost('/api/v1/time-entries', { entries });

    return payload.data ?? [];
}

export async function getTimeEntries(companyId = null) {
    const params = new URLSearchParams();

    if (companyId) {
        params.set('filter[company_id]', companyId);
    }

    const query = params.toString();
    const payload = await apiGet(`/api/v1/time-entries${query ? `?${query}` : ''}`);

    return payload.data ?? [];
}
<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { RefreshCw } from 'lucide-vue-next';
import { getTimeEntries } from '@/api/options';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';

const props = defineProps({
    historyRefreshKey: { type: Number, default: 0 },
    selectedCompanyId: { type: [String, null], default: null },
});

const entries = ref([]);
const error = ref(null);
const isLoading = ref(false);
const loadToken = ref(0);

const totalHours = computed(() => entries.value.reduce((total, entry) => total + Number.parseFloat(entry.hours ?? 0), 0));
const scopeLabel = computed(() => props.selectedCompanyId ? 'Company scope' : 'All companies');

async function loadEntries() {
    const token = loadToken.value + 1;
    loadToken.value = token;
    const companyId = props.selectedCompanyId;

    isLoading.value = true;
    error.value = null;

    try {
        const nextEntries = await getTimeEntries(companyId);

        if (token === loadToken.value) {
            entries.value = nextEntries;
        }
    } catch (exception) {
        if (token === loadToken.value) {
            error.value = exception;
        }
    } finally {
        if (token === loadToken.value) {
            isLoading.value = false;
        }
    }
}

function relatedName(entry, relation) {
    return entry[relation]?.name ?? 'Unknown';
}

onMounted(loadEntries);
watch(() => props.selectedCompanyId, loadEntries);
watch(() => props.historyRefreshKey, loadEntries);
</script>

<template>
    <div class="space-y-4">
        <div class="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between">
            <div>
                <h2 class="text-lg font-semibold tracking-[-0.02em]">History</h2>
                <p class="text-sm text-muted-foreground">Read-only time entries from the API.</p>
            </div>
            <div class="flex items-center gap-2">
                <Badge variant="secondary">{{ scopeLabel }}</Badge>
                <Badge variant="outline">{{ entries.length }} entries</Badge>
                <Badge variant="outline">{{ totalHours.toFixed(2) }} hours</Badge>
                <Button variant="ghost" size="icon-sm" :disabled="isLoading" @click="loadEntries">
                    <RefreshCw :class="isLoading ? 'animate-spin' : ''" />
                </Button>
            </div>
        </div>

        <section class="overflow-hidden rounded-xl border border-border bg-card shadow-[inset_0_1px_0_rgb(255_255_255/0.04)]">
            <Table>
                <TableHeader>
                    <TableRow class="bg-background/70 hover:bg-background/70">
                        <TableHead>Company</TableHead>
                        <TableHead>Date</TableHead>
                        <TableHead>Employee</TableHead>
                        <TableHead>Project</TableHead>
                        <TableHead>Task</TableHead>
                        <TableHead class="text-right">Hours</TableHead>
                    </TableRow>
                </TableHeader>
                <TableBody>
                    <TableRow v-if="isLoading">
                        <TableCell colspan="6" class="py-8 text-center text-sm text-muted-foreground">
                            Loading history
                        </TableCell>
                    </TableRow>
                    <TableRow v-else-if="error">
                        <TableCell colspan="6" class="py-8 text-center text-sm text-destructive">
                            {{ error.message }}
                        </TableCell>
                    </TableRow>
                    <TableRow v-else-if="entries.length === 0">
                        <TableCell colspan="6" class="py-8 text-center text-sm text-muted-foreground">
                            No time entries found for this scope.
                        </TableCell>
                    </TableRow>
                    <TableRow v-for="entry in entries" v-else :key="entry.id">
                        <TableCell>{{ relatedName(entry, 'company') }}</TableCell>
                        <TableCell class="whitespace-nowrap">{{ entry.entry_date_display ?? entry.entry_date }}</TableCell>
                        <TableCell>{{ relatedName(entry, 'employee') }}</TableCell>
                        <TableCell>{{ relatedName(entry, 'project') }}</TableCell>
                        <TableCell>{{ relatedName(entry, 'task') }}</TableCell>
                        <TableCell class="text-right tabular-nums">
                            {{ entry.hours_display ?? entry.hours }}
                        </TableCell>
                    </TableRow>
                </TableBody>
            </Table>
        </section>
    </div>
</template>

import { expect, test } from '@playwright/test';

test.beforeEach(async ({ page }) => {
    await page.goto('/entries/history');
    await expect(page.getByRole('heading', { name: 'History' })).toBeVisible();
});

test('lists time entries from the history API', async ({ page }) => {
    await expect(page.getByRole('cell', { name: 'Acme Operations' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Ava Chen' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Website Redesign' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Development' }).first()).toBeVisible();
    await expect(page.getByText(/entries$/).first()).toBeVisible();
});

test('filters history when the global company scope changes', async ({ page }) => {
    await page.getByRole('button', { name: 'All companies' }).click();
    await page.getByRole('option', { name: 'Globex Services' }).click();

    await expect(page.getByRole('cell', { name: 'Globex Services' }).first()).toBeVisible();
    await expect(page.getByRole('cell', { name: 'Acme Operations' })).toHaveCount(0);
    await expect(page.getByText('Company scope')).toBeVisible();
});

test('shows a newly submitted entry after switching to history', async ({ page }) => {
    const entryDate = formatDate(new Date(new Date().getFullYear(), new Date().getMonth(), 20));
    const entryDateDisplay = new Date(`${entryDate}T00:00:00`).toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
    });

    await page.goto('/entries/new');
    await expect(page.getByRole('heading', { name: 'New Entries' })).toBeVisible();

    const firstRow = page.locator('tbody tr').first();

    await selectSpreadsheetOption(page, firstRow, 'Select company', 'Acme Operations');
    await selectDate(page, firstRow, entryDate);
    await selectSpreadsheetOption(page, firstRow, 'Select employee', 'Ben Carter');
    await selectSpreadsheetOption(page, firstRow, 'Select project', 'Website Redesign');
    await selectSpreadsheetOption(page, firstRow, 'Select task', 'Planning');
    await firstRow.getByPlaceholder('0.00').fill('7.75');
    await page.getByRole('button', { name: 'Submit batch' }).click();

    await expect(page.getByText('Time entries saved.')).toBeVisible();
    await page.getByRole('link', { name: 'History' }).click();

    await expect(page.getByRole('heading', { name: 'History' })).toBeVisible();
    const createdRow = page.getByRole('row').filter({ has: page.getByRole('cell', { name: entryDateDisplay }) }).first();

    await expect(createdRow.getByRole('cell', { name: 'Ben Carter' })).toBeVisible();
    await expect(createdRow.getByRole('cell', { name: 'Planning' })).toBeVisible();
    await expect(createdRow.getByRole('cell', { name: '7.75' })).toBeVisible();
});

async function selectSpreadsheetOption(page, row, triggerName, optionName) {
    await row.getByRole('button', { name: triggerName }).click();
    await page.getByRole('option', { name: optionName }).click();
