<?php

namespace App\QueryBuilders;

use App\Models\TimeEntry;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Http\Request;
use Illuminate\Pagination\LengthAwarePaginator;
use Illuminate\Support\Str;
use Spatie\QueryBuilder\AllowedFilter;
use Spatie\QueryBuilder\QueryBuilder;

class TimeEntryIndexQuery extends QueryBuilder
{
    public function __construct(private readonly Request $baseRequest)
    {
        $query = TimeEntry::query()
            ->select([
                'id',
                'company_id',
                'employee_id',
                'project_id',
                'task_id',
                'entry_date',
                'hours',
                'created_at',
                'updated_at',
            ])
            ->with([
                'company:id,name,created_at,updated_at',
                'employee:id,name,email,created_at,updated_at',
                'project:id,company_id,name,created_at,updated_at',
                'task:id,company_id,name,created_at,updated_at',
            ]);

        parent::__construct($query, $baseRequest);

        $this
            ->allowedFilters(
                AllowedFilter::exact('company_id'),
                AllowedFilter::callback('search', function (Builder $query, mixed $value): void {
                    $search = Str::of($value)->trim()->toString();

                    if ($search === '') {
                        return;
                    }

                    $pattern = "{$search}%";

                    $query->where(function (Builder $query) use ($pattern): void {
                        $query
                            ->whereHas('company', fn (Builder $query) => $query->where('name', 'like', $pattern))
                            ->orWhereHas('employee', fn (Builder $query) => $query->where('name', 'like', $pattern))
                            ->orWhereHas('project', fn (Builder $query) => $query->where('name', 'like', $pattern))
                            ->orWhereHas('task', fn (Builder $query) => $query->where('name', 'like', $pattern));
                    });
                }),
            )
            ->allowedSorts('entry_date', 'created_at', 'hours')
            ->defaultSort('-entry_date', '-created_at');
    }

    public function jsonPaginate(): LengthAwarePaginator
    {
        return $this
            ->paginate($this->perPage(), ['*'], 'page')
            ->appends($this->baseRequest->query());
    }

    private function perPage(): int
    {
        return min(max($this->baseRequest->integer('per_page', 10), 1), 50);
    }
}
import { apiGet, apiPost } from './client';

export async function getCompanies() {
    const payload = await apiGet('/api/v1/companies');

    return payload.data ?? [];
}

export async function getCompanyEmployees(companyId) {
    const payload = await apiGet(`/api/v1/companies/${companyId}/employees`);

    return payload.data ?? [];
}

export async function getCompanyProjects(companyId, employeeId = null) {
    const params = new URLSearchParams();

    if (employeeId) {
        params.set('filter[employee_id]', employeeId);
    }

    const query = params.toString();
    const payload = await apiGet(`/api/v1/companies/${companyId}/projects${query ? `?${query}` : ''}`);

    return payload.data ?? [];
}

export async function getCompanyTasks(companyId) {
    const payload = await apiGet(`/api/v1/companies/${companyId}/tasks`);

    return payload.data ?? [];
}

export async function createTimeEntries(entries) {
    const payload = await apiPost('/api/v1/time-entries', { entries });

    return payload.data ?? [];
}

export async function getTimeEntries(options = {}) {
    const normalizedOptions = typeof options === 'string'
        ? { companyId: options }
        : options ?? {};
    const params = new URLSearchParams();

    if (normalizedOptions.companyId) {
        params.set('filter[company_id]', normalizedOptions.companyId);
    }

    if (normalizedOptions.search) {
        params.set('filter[search]', normalizedOptions.search);
    }

    if (normalizedOptions.page) {
        params.set('page', normalizedOptions.page);
    }

    if (normalizedOptions.perPage) {
        params.set('per_page', normalizedOptions.perPage);
    }

    const query = params.toString();
    const payload = await apiGet(`/api/v1/time-entries${query ? `?${query}` : ''}`);

    return {
        entries: payload.data ?? [],
        links: payload.links ?? {},
        meta: payload.meta ?? {},
    };
}

