const emit = defineEmits(['submitted']);

const companiesRef = computed(() => props.companies);

const nextDraftRowId = ref(1);
const rows = ref([makeRow(), makeRow()]);
const errors = ref({});
const submitError = ref(null);
const submitState = ref('idle');
