+
+class TimeEntryDraftAgent implements Agent, HasStructuredOutput
+{
+    use Promptable;
+
+    public function instructions(): string
+    {
+        return <<<'PROMPT'
+You convert plain-English time entry notes into structured draft rows for a time entry spreadsheet.
+
+Return draft rows only. Do not invent people, companies, projects, or tasks that are not mentioned or strongly implied by the user's text and reference data. Preserve the user's dates as ISO YYYY-MM-DD when possible. If a value is unclear, leave that field empty and add a short warning.
+
+Each row represents one task entry with company, employee, project, task, entry_date, and hours. Multiple tasks for the same employee, project, and date should be returned as separate rows.
+PROMPT;
+    }
+
+    public function schema(JsonSchema $schema): array
+    {
+        return [
+            'entries' => $schema->array()
+                ->items($schema->object([
+                    'company' => $schema->string()->description('Company name or empty string.')->required(),
+                    'employee' => $schema->string()->description('Employee name or empty string.')->required(),
+                    'project' => $schema->string()->description('Project name or empty string.')->required(),
