+     * @return array<string, mixed>
+     */
+    private function resolveEntry(array $entry, AiTimeEntryPromptData $data, Collection $companies): array
+    {
+        $warnings = collect([$entry['warning'] ?? null])->filter()->values();
+        $company = $this->resolveCompany($entry, $data, $companies);
+
+        if (! $company instanceof Company) {
+            $warnings->push('Choose a company before saving this row.');
+        }
+
+        $employee = $company instanceof Company
+            ? $this->resolveByName($company->employees, $entry['employee'] ?? null)
+            : null;
+        $project = $company instanceof Company
+            ? $this->resolveByName($company->projects, $entry['project'] ?? null)
+            : null;
+        $task = $company instanceof Company
+            ? $this->resolveByName($company->tasks, $entry['task'] ?? null)
+            : null;
+
+        if (! $employee instanceof Employee) {
+            $warnings->push('Choose a matching employee.');
+        }
+
+        if (! $project instanceof Project) {
+            $warnings->push('Choose a matching project.');
+        }
+
+        if (! $task instanceof Task) {
+            $warnings->push('Choose a matching task.');
+        }
+
+        if ($employee instanceof Employee && $project instanceof Project && ! $this->employeeIsAssigned($employee, $project, $company)) {
+            $warnings->push('The matched employee is not assigned to the matched project.');
+        }
+
+        return [
+            'company_id' => $company?->id,
+            'company_name' => $company?->name ?? $this->text($entry['company'] ?? null),
+            'employee_id' => $employee?->id,
+            'employee_name' => $employee?->name ?? $this->text($entry['employee'] ?? null),
+            'project_id' => $project?->id,
+            'project_name' => $project?->name ?? $this->text($entry['project'] ?? null),
+            'task_id' => $task?->id,
+            'task_name' => $task?->name ?? $this->text($entry['task'] ?? null),
+            'entry_date' => $this->date($entry['entry_date'] ?? null),
+            'hours' => $entry['hours'] ?? null,
+            'warnings' => $warnings->unique()->values()->all(),
+        ];
+    }
+
+    /**
+     * @param  array<string, mixed>  $entry
+     * @param  Collection<int, Company>  $companies
+     */
+    private function resolveCompany(array $entry, AiTimeEntryPromptData $data, Collection $companies): ?Company
+    {
+        if ($data->company_id !== null) {
+            return $companies->firstWhere('id', $data->company_id);
+        }
+
+        return $this->resolveByName($companies, $entry['company'] ?? null);
+    }
+
+    /**
+     * @param  Collection<int, mixed>  $records
+     */
+    private function resolveByName(Collection $records, mixed $name): mixed
+    {
+        $normalized = $this->normalize($name);
+
+        if ($normalized === '') {
+            return null;
+        }
+
+        $matches = $records->filter(fn (mixed $record): bool => $this->normalize($record->name ?? null) === $normalized);
+
+        if ($matches->count() !== 1) {
+            return null;
+        }
+
+        return $matches->first();
+    }
+
+    private function employeeIsAssigned(Employee $employee, Project $project, ?Company $company): bool
+    {
+        if (! $company instanceof Company) {
+            return false;
+        }
+
+        return $employee->projects->contains(
+            fn (Project $assignedProject): bool => $assignedProject->id === $project->id
+                && $assignedProject->pivot->company_id === $company->id
+        );
+    }
+
+    private function date(mixed $value): ?string
+    {
+        $text = $this->text($value);
+
+        if ($text === '') {
+            return null;
+        }
+
+        try {
+            return Carbon::parse($text)->toDateString();
+        } catch (\Throwable) {
+            return null;
+        }
+    }
+
+    private function normalize(mixed $value): string
+    {
+        return Str::of($this->text($value))->lower()->squish()->toString();
+    }
+
+    private function text(mixed $value): string
+    {
+        if ($value === null) {
+            return '';
+        }
+
+        return Str::of($value)->trim()->toString();
+    }
+}
